def maxDifference(s: str) -> int:
    from collections import Counter
    frequencies = Counter(s)
    odd_freqs = [freq for freq in frequencies.values() if freq % 2 == 1]
    even_freqs = [freq for freq in frequencies.values() if freq % 2 == 0]
    if odd_freqs and even_freqs:
        return max(odd_freqs) - min(even_freqs)
    return 0

from typing import List

def sumOfGoodNumbers(nums: List[int], k: int) -> int:
    total = 0
    n = len(nums)
    for i in range(n):
        is_good = True
        if i - k >= 0 and nums[i] <= nums[i - k]:
            is_good = False
        if i + k < n and nums[i] <= nums[i + k]:
            is_good = False
        if is_good:
            total += nums[i]
    return total

