from typing import List

def maxSum(nums: List[int]) -> int:
    unique_values = set()  # To store unique elements
    max_sum = 0  # Sum of positive unique values
    best_negative = float('-inf')  # To track the best negative value
    for num in nums:
        if num not in unique_values:
            unique_values.add(num)  # Add to set if unique
            if num > 0:
                max_sum += num  # Sum positive unique values
            else:
                best_negative = max(best_negative, num)  # Track largest negative value
    return max_sum if max_sum > 0 else best_negative

