from typing import List


def minMaxWeight(n: int, edges: List[List[int]], threshold: int) -> int:
    from collections import defaultdict, deque

    # Build the reverse graph
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[v].append((u, w))  # Reverse the direction

    # Function to check if we can reach node 0 with a certain max weight
    def canReachMaxWeight(maxWeight: int) -> bool:
        outgoing_count = defaultdict(int)
        queue = deque([0])
        visited = set([0])

        while queue:
            node = queue.popleft()
            for neighbor, weight in graph[node]:
                if weight <= maxWeight and outgoing_count[node] < threshold:
                    outgoing_count[node] += 1
                    if neighbor not in visited:
                        visited.add(neighbor)
                        queue.append(neighbor)
        return len(visited) == n

    # Binary search for the minimum possible maximum edge weight
    left, right = 1, 10**6
    result = -1

    while left <= right:
        mid = (left + right) // 2
        if canReachMaxWeight(mid):
            result = mid
            right = mid - 1
        else:
            left = mid + 1

    return result

from typing import List

def minCost(n: int, cost: List[List[int]]) -> int:
    # DP table for the current and previous states
    dp = [[float('inf')] * 3 for _ in range(3)]

    # Initialize DP for the first house and the last house
    for a in range(3):
        for b in range(3):
            if a != b:
                dp[a][b] = cost[0][a] + cost[n - 1][b]  # First and last houses must be different

    # DP for every pair of houses
    for i in range(1, n // 2):  # only need to iterate through half the houses
        new_dp = [[float('inf')] * 3 for _ in range(3)]
        for a in range(3):
            for b in range(3):
                if a != b:
                    current_cost = cost[i][a] + cost[n - 1 - i][b]
                    for prev_a in range(3):
                        for prev_b in range(3):
                            if a != prev_a and b != prev_b:
                                new_dp[a][b] = min(new_dp[a][b], dp[prev_a][prev_b] + current_cost)
        dp = new_dp

    # Find the minimum cost from the last DP stage
    res = float('inf')
    for a in range(3):
        for b in range(3):
            if a != b:
                res = min(res, dp[a][b])

    return res

from typing import List


def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    events_sorted = sorted(events, key=lambda x: (int(x[1]), x[0] == 'MESSAGE'))

    for event in events_sorted:
        event_type, timestamp, *details = event
        timestamp = int(timestamp)

        if event_type == "OFFLINE":
            user_id = int(details[0])
            online_status[user_id] = False

        elif event_type == "MESSAGE":
            mentions_string = details[0].split()
            mentioned_users = []

            for mention in mentions_string:
                if mention.startswith("id"):
                    user_id = int(mention[2:])
                    mentioned_users.append(user_id)
                elif mention == "ALL":
                    mentioned_users.extend(range(numberOfUsers))
                elif mention == "HERE":
                    mentioned_users.extend(i for i in range(numberOfUsers) if online_status[i])

            for user_id in mentioned_users:
                mentions[user_id] += 1

        # Process user statuses: Users come back online after 60 time units
        for i in range(numberOfUsers):
            if not online_status[i] and timestamp >= (timestamp if events_sorted[i][0] == 'OFFLINE' else timestamp + 60):
                online_status[i] = True

    return mentions

