def maxDistance(s: str, k: int) -> int:
    x, y = 0, 0
    max_distance = 0
    for prefix_length, char in enumerate(s, start=1):
        if char == 'N':
            y += 1
        elif char == 'S':
            y -= 1
        elif char == 'E':
            x += 1
        elif char == 'W':
            x -= 1
        # Calculate current distance
        current_distance = abs(x) + abs(y)
        # Calculate the possible maximum distance after changes
        possible_distance = min(prefix_length, current_distance + 2 * k)
        max_distance = max(max_distance, possible_distance)
    return max_distance

